if HD>yD- #AD then
local JD=F.gameSaid(ED)
F.log(1,jse[2620],string.format(jse[2625],#AD,tostring(JD or GD or jse[2626])))
F.backoff(jse[2623],1800)
return
end
cb.add(string.format(jse[2627],#AD),#AD,jse[2628],string.format(jse[2629],zD-HD,zD,table.concat(BD,jse[2630])))
end
function mb.weatherStrength(KD)
local LD=mb.fx(KD)
local MD=LD.dmg/LD.cd/LD.hp/LD.speed*(1+(LD.range-1)/2)
for ND,OD in pairs(LD.kinds)do
MD=MD*(1+bb.rogueShare(ND)*OD)
end
if LD.ice>0 then
local PD=bb.rogueShare(jse[2225])
MD=MD*(PD+(1-PD)/(1-LD.ice+LD.ice/gb.modFactor(jse[2631])))
end
if LD.fly>0 then
MD=MD*(1-LD.fly*0.5)
end
if LD.noCC then
MD=MD*0.95
end
if LD.shroud then
MD=MD*0.9
end
if LD.zap then
MD=MD*0.85
end
return MD/mb.weatherK(KD)
end
mb.WEATHER_K_MIN,mb.WEATHER_K_MAX,mb.WEATHER_K_RUNS=0.5,4,10
function mb.weatherK(QD)
local RD=QD and type(P.hunt)==jse[2091]and type(P.hunt.wk)==jse[2091]and P.hunt.wk[tostring(QD)]or nil
return type(RD)==jse[2091]and tonumber(RD.k)or 1
