function mb.weatherLearn()
if bb.withOthers or#game:GetService(jse[989]):GetPlayers()>1 then
return
end
local SD=bb.huntWeather or mb.weatherNow()
local TD,UD=bb.pred,bb.calRun
if not SD or type(TD)~=jse[2091]or type(UD)~=jse[2091]then
return
end
local function VD(WD,XD)
return type(WD)==jse[2091]and tonumber(WD[XD]or WD[tostring(XD)])or nil
end
local YD={}
for ZD=2,bb.wave()do
local _D,aE=VD(UD.alive,ZD),VD(TD.aliveAt,ZD)
if _D and aE and _D>0 and aE>0 then
table.insert(YD,_D/aE)
end
end
if#YD<3 then
return
end
table.sort(YD)
local bE=YD[math.ceil(#YD/2)]
P.hunt.wk=type(P.hunt.wk)==jse[2091]and P.hunt.wk or{}
local cE=P.hunt.wk[tostring(SD)]
local dE=math.min(mb.WEATHER_K_RUNS-1,type(cE)==jse[2091]and tonumber(cE.n)or 0)
local eE=mb.weatherK(SD)
local fE=math.max(1,dE)
local gE=math.exp((fE*math.log(eE)+math.log(eE*bE))/(fE+1))
gE=U.clamp(gE,mb.WEATHER_K_MIN,mb.WEATHER_K_MAX)
bb.wkWas={w=tostring(SD),old=cE}
P.hunt.wk[tostring(SD)]={k=gE,n=(type(cE)==jse[2091]and tonumber(cE.n)or 0)+1,at=os.time()}
F.log(1,jse[2632],string.format(jse[2633],tostring(SD),bE,tostring(SD),gE,eE,P.hunt.wk[tostring(SD)].n))
end
function mb.cardGems(hE,iE)
