W.MATCHED_DAILY_P=0.7
function W.icWinP(qP)
local rP=qP.rec or W.rec(qP.key)
local sP=W.icLost(qP.room)
local tP=sP and sP.n or 0
local uP=((tonumber(rP.wins)or 0)+(qP.p0 or W.PRIOR_WIN.castle)*2)/((tonumber(rP.runs)or 0)+2)
local vP=W.sim(qP)
local wP,xP=0,0
if vP and tonumber(vP.p)then
local yP=type(vP.trust)==jse[2091]and vP.trust or nil
local zP=yP~=nil and not yP.ok
local AP=zP and(tonumber(yP.ratio)or 1)>1
if not zP or(AP and not vP.won)or(zP and not AP and vP.won)then
local BP,CP=pcall(gb.styleP,vP)
wP,xP=(BP and tonumber(CP))or tonumber(vP.p),W.IC.SIM_W
end
end
return(uP*2+wP*xP)/(tP+2+xP)
end
function W.winP(DP)
if DP.kind==jse[2546]then
return W.icWinP(DP)
end
if DP.kind==jse[2544]and O.dailyMatch and not O.dailyLoop then
local FP,GP=pcall(W.needsHelp,DP)
if FP and GP then
return W.MATCHED_DAILY_P
end
end
local HP=DP.rec
local IP=DP.p0 or W.PRIOR_WIN[DP.kind]or 0.7
local JP=W.sim(DP)
if JP and not(JP.trust and not JP.trust.ok)then
local KP=JP.calibrated or HP.runs>0
local LP=(JP.trust and JP.trust.ok)and 6 or(KP and 3 or 1.5)
local MP=(KP or JP.hopeless)and 0 or 2
local NP,OP=pcall(gb.styleP,JP)
return(HP.wins+IP*MP+(NP and OP or JP.p)*LP)/(HP.runs+MP+LP)
end
return(HP.wins+IP*2)/(HP.runs+2)
end
function W.minutes(PP)
