return TP+W.OVERHEAD
end
function W.score(UP)
local VP,WP=((UP.kind==jse[2109]and UP.rec.runs>0)or UP.kind==jse[2111]or UP.kind==jse[2547])and 1 or(UP.kind==jse[2112]and UP.p0)or W.winP(UP),W.minutes(UP)
