if XP and(YP or 0)>0 then
UP.teamBonus=YP
if not tostring(UP.why):find(jse[2820],1,true)then
UP.why=(UP.why or jse[1010])..jse[2467]..ZP
end
end
local _P=VP*(UP.value+(UP.teamBonus or 0))/WP
UP.baseScore=_P
local aQ,bQ,cQ=pcall(ib.valueFor,UP)
if aQ and bQ>0 then
local dQ=VP*(UP.value+bQ)/(WP*cQ)
if dQ>_P then
_P,UP.train=dQ,bQ
end
end
if UP.rec.runs<2 then
_P=_P*(1+O.exploreBonus)
