db.STUDY_WORDS={jse[2178],jse[2853],jse[2302],jse[2854],jse[2855],jse[2856],jse[2857],jse[2858],jse[2859],jse[2860],jse[2341],jse[2275],jse[2211],jse[2209],jse[2223],jse[1933],jse[1931],jse[1939],jse[2236],jse[2344],jse[2861],jse[2862],jse[2863],jse[2864],jse[2865],jse[2866],jse[2867],jse[2868],jse[2869],jse[2870],jse[2871],jse[2296],jse[2872],jse[2873]}
function db.r3(BR)
BR=tonumber(BR)
return BR and math.floor(BR*1000+0.5)/1000 or nil
end
function db.atkBrief(CR)
if type(CR)~=jse[2091]then
return nil
end
local DR={n=db.r3(CR.n),hits=CR.hits}
if(CR.slow or 0)>0 then
DR.slow=db.r3(CR.slowPct)
DR.slowTime=db.r3(CR.slowTime)
end
if(CR.stun or 0)>0 then
DR.stun=db.r3(CR.stun)
end
if(CR.dot or 0)>0 then
DR.dot=db.r3(CR.dot)
end
if CR.bleed then
DR.bleed=true
end
if(CR.amp or 0)>0 then
DR.amp=db.r3(CR.amp)
end
if CR.full then
DR.full=true
end
if CR.wholeMap then
DR.wholeMap=true
end
if CR.breakShields then
DR.breakShields=true
end
if CR.ally then
DR.allyBuff=CR.ally.types
DR.allyTime=CR.ally.time
end
if CR.allyCd then
DR.allyCd=CR.allyCd
end
if CR.allyRange then
DR.allyRange=CR.allyRange
end
if CR.selfDmg then
DR.selfDmg=CR.selfDmg
end
if CR.baseSafe then
DR.baseSafe=CR.baseSafe
end
return DR
end
function db.readPassives(ER)
local FR=V.field(ER,jse[2201])
local GR={}
for HR,IR in pairs(type(FR)==jse[2091]and FR or{})do
if type(IR)==jse[2091]then
local JR=tostring(IR.description or jse[1010]):gsub(jse[2243],jse[1010]):gsub(jse[2312],jse[2313])
local KR=JR:lower()
local LR={name=tostring(IR.name or HR),text=JR:sub(1,400)}
local MR={}
for NR in KR:gmatch(jse[2874])do
if tonumber(NR)then
table.insert(MR,tonumber(NR))
end
end
if#MR>0 then
LR.pct=MR
end
LR.every=tonumber(KR:match(jse[2875]))or tonumber(KR:match(jse[2876]))or tonumber(KR:match(jse[2877]))
LR.sec=tonumber(KR:match(jse[2878]))
LR.upTo=tonumber(KR:match(jse[2254]))
local OR={}
for PR,QR in ipairs(db.STUDY_WORDS)do
if KR:find(QR,1,true)then
table.insert(OR,QR)
end
end
if#OR>0 then
LR.tags=OR
end
table.insert(GR,LR)
end
end
table.sort(GR,function(RR,SR)
return RR.name<SR.name
end)
return GR
end
function db.readAbility(TR)
