local bS=V.field(TR,jse[2199])
return{id=VR,name=type(YR)==jse[2091]and type(YR.name)==jse[996]and YR.name or nil,text=aS,from=WR,cd=type(bS)==jse[2091]and tonumber(bS.attack_cooldown)or(UR and WR and UR[WR]and UR[WR].activeCd)or nil,does=ZR and db.atkBrief(_R)or nil}
