function db.readAttacks(cS)
local dS=V.rows(cS)
local eS,fS={},nil
for gS=0,dS and dS.max or-1 do
local hS=dS[gS]
if hS and hS.atk and hS.atk~=fS then
fS=hS.atk
local iS,jS=pcall(V.attackInfo,hS.atk,hS.range)
table.insert(eS,{from=gS,id=hS.atk,does=iS and db.atkBrief(jS)or nil})
