function ab.autoFuseXp()
if not O.autoFuseXp or O.fuseXpUnit==jse[1010]then
return
end
local fgb=N.session()
local ggb=ab.fuseXpTarget(fgb)
if not ggb then
return
end
local hgb=V.name(ggb.unit_id)
local igb,jgb,kgb=ab.xpFodder(ggb)
if kgb<=0 then
ab.pickNote.autoFuseXp=nil
return
end
if#igb==0 then
ab.pickNote.autoFuseXp=jse[3226]
return
end
if os.time()-(tonumber(O.fuseXpOnAt)or 0)<30 then
ab.pickNote.autoFuseXp=jse[3227]
return
end
ab.pickNote.autoFuseXp=nil
if F.req.back.fuseXp and U.now()<F.req.back.fuseXp then
return
end
ab.fuseBatch=ab.fuseBatch or 50
local lgb,mgb,ngb=0,0,{}
while F.alive and lgb<10 and not P.pauseAll do
if lgb>0 then
local ogb,pgb,qgb=ab.xpFodder(fgb.collection:get_unit_by_uuid(O.fuseXpUnit)or ggb)
igb,kgb={},qgb
for rgb,sgb in ipairs(ogb)do
if not ngb[sgb.uuid]then
table.insert(igb,sgb)
end
end
if kgb<=0 or#igb==0 then
break
end
end
local tgb={}
for ugb=1,math.min(ab.fuseBatch,#igb)do
table.insert(tgb,igb[ugb].uuid)
end
