if ygb==jse[2165]or mgb>=3 then
break
end
mgb=mgb+1
task.wait(3.5)
continue
end
while U.now()-wgb<5 and(tonumber((fgb.collection:get_unit_by_uuid(O.fuseXpUnit)or ggb).xp)or 0)<=vgb do
task.wait(0.1)
end
local zgb=tonumber((fgb.collection:get_unit_by_uuid(O.fuseXpUnit)or ggb).xp)or 0
if zgb>vgb then
lgb=lgb+1
for Agb,Bgb in ipairs(tgb)do
ngb[Bgb]=true
end
cb.add(string.format(jse[3230],#tgb,hgb),#tgb,jse[3231],string.format(jse[3232],U.fmt(zgb-vgb)))
F.log(1,jse[2596],string.format(jse[3233],#tgb,hgb,U.fmt(zgb-vgb),kb.level(fgb.collection:get_unit_by_uuid(O.fuseXpUnit)or ggb)))
elseif#tgb>20 then
ab.fuseBatch=20
F.log(1,jse[2596],string.format(jse[3234],#tgb,tostring(F.gameSaid(wgb)or(xgb and ygb)or jse[2626])))
else
local Cgb=F.gameSaid(wgb)
ab.pickNote.autoFuseXp=jse[3235]..tostring(Cgb or(xgb and ygb)or jse[2626])..jse[3236]
F.log(1,jse[2596],jse[3237]..tostring(Cgb or(xgb and ygb)or jse[2626]))
F.backoff(jse[3228],1800)
break
end
end
end
