if Irb and not Irb.legend_stage and not Irb.raid_world then
local Jrb=U.list(Irb.levels)
local Krb=Jrb[#Jrb]
if Krb and not W.done(Crb,Krb.id,jse[1015])then
Drb,Erb,Frb=Hrb,Jrb[1],Krb
break
end
end
end
if not(Drb and Brb[Drb]and Erb and Frb)then
