end
if W.open(Frb.id)or not W.open(Erb.id)then
return
end
P.worldSkip=type(P.worldSkip)==jse[2091]and P.worldSkip or{}
local Lrb=P.worldSkip[Drb]
if type(Lrb)==jse[2091]and(Lrb.done or os.time()-(tonumber(Lrb.at)or 0)<ab.WORLD_SKIP_RETRY)then
return
end
local Mrb=N.Worlds[Drb]
local Nrb=tostring(Mrb and Mrb.name or Drb)
local Orb={key=jse[2780]..Frb.id..jse[2886],kind=jse[2131],first=true,level=Frb.id,diff=jse[1015],label=W.levelName(Frb.id)..jse[2887]}
