F.log(1,jse[2713],string.format(jse[3484],Nrb,W.levelName(Frb.id),tostring(Qrb.margin)))
local Vrb,Wrb=F.request(jse[3485],jse[3486],Drb)
local Xrb=false
while U.now()-Urb<8 do
task.wait(1)
if W.open(Frb.id)then
Xrb=true
break
end
end
local Yrb=F.gameSaid(Urb)
P.worldSkip[Drb]={at=os.time(),done=Xrb or nil,last=Frb.id,said=Yrb and tostring(Yrb):sub(1,80)or nil}
F.saveSoon()
if Xrb then
local Zrb=(N.prof()or{}).level_data or{}
local _rb={}
for asb,bsb in ipairs(U.list(Mrb.levels))do
if bsb.id~=Frb.id and not Rrb[bsb.id]and W.done(Zrb,bsb.id,jse[1015])then
table.insert(_rb,W.levelName(bsb.id))
end
end
F.log(1,jse[2713],string.format(jse[3487],Nrb,#_rb>0 and(jse[3488]..table.concat(_rb,jse[2204]))or jse[3489],Yrb and(jse[3490]..tostring(Yrb))or jse[1010]))
W.lastScored=nil
