if zvb and zvb.item_id and(N.Items[zvb.item_id]or{}).unique_equip then
table.insert(vvb,{uuid=xvb,u=yvb,kind=zvb.item_id,relic=yvb._equipped_relic,k=(svb[xvb]and 1e12 or 0)+kb.score(yvb)})
end
