P.relicOff[Evb.uuid]=Evb.relic
F.log(1,jse[3141],string.format(jse[3600],V.name(Evb.u.unit_id),Fvb,V.name(Cvb[Evb.kind])))
else
F.log(1,jse[3141],string.format(jse[3601],V.name(Evb.u.unit_id),Fvb,tostring(Hvb)))
