end
Xvb={}
for xwb,ywb in ipairs(V.equipped())do
Xvb[ywb.uuid]=true
end
end
W._sigAt=nil
if hwb then
F.log(1,jse[3141],jse[3608].. #Vvb..jse[3609]..tostring(Wvb))
else
local zwb={}
for Awb,Bwb in ipairs(V.equipped())do
table.insert(zwb,V.name(Bwb.id))
end
F.log(1,jse[3141],jse[3610]..tostring(Wvb)..jse[3611]..table.concat(zwb,jse[2204])..jse[3612]..table.concat(iwb,jse[2467]))
if not ab.refilling and#V.equipped()<6 then
ab.refilling=true
local Cwb,Dwb={},{}
