function ab.unitLabSafe(oxb)
if O.unitLab==false or type(oxb)~=jse[2091]or not ab.LAB.KINDS[oxb.kind]or oxb.first then
return false
end
if P.trial or(P.study and not P.study.done)or(type(P.testTeam)==jse[2091]and(tonumber(P.testTeam.left)or 0)>0)or(P.train and P.train.on)or ab.partyRole()~=jse[1016]then
return false
end
local pxb,qxb=pcall(ab.matchOn,oxb)
if pxb and qxb then
return false
end
local rxb=type(P.unitLab)==jse[2091]and P.unitLab or{}
if rxb.pauseKey==oxb.key and os.time()<(tonumber(rxb.pauseUntil)or 0)then
return false
end
local sxb=W.rec(oxb.key)
local txb,uxb=tonumber(sxb.runs)or 0,tonumber(sxb.wins)or 0
if oxb.kind==jse[2111]then
local vxb,wxb=pcall(W.infDaily,N.prof(),oxb.level,W.infReach(oxb.key))
return txb>=3 and vxb and(tonumber(wxb)or 1)<=0
end
return txb>=5 and(tonumber(sxb.streak)or 0)==0 and uxb/txb>=0.9
end
function ab.unitLab(xxb)
if not ab.unitLabSafe(xxb)then
return
end
P.unitLab=type(P.unitLab)==jse[2091]and P.unitLab or{}
local yxb=P.unitLab
yxb.tried=type(yxb.tried)==jse[2091]and yxb.tried or{}
yxb.seen=(tonumber(yxb.seen)or 0)+1
if yxb.seen%ab.LAB.EVERY~=0 then
return
end
local zxb=N.session()
local Axb=V.equipped()
if not zxb or#Axb<2 then
return
end
local Bxb={}
for Cxb,Dxb in ipairs(Axb)do
Bxb[Dxb.uuid]=true
Bxb[Dxb.id]=true
end
local Exb,Fxb,Gxb
for Hxb,Ixb in pairs(zxb.profile_data.collection.owned_units)do
local Jxb=Ixb.unit_id
if not Bxb[Hxb]and not Bxb[Jxb]and N.Units[Jxb]and not V.isFarm(Jxb)and not V.allyBuff(Jxb)and os.time()-(tonumber(yxb.tried[Jxb])or 0)>ab.LAB.AGAIN then
local Kxb=ab.unitEvidence(Jxb)
if Kxb<ab.LAB.MIN_EVIDENCE then
local Lxb=zxb.collection:get_unit_by_uuid(Hxb)or Ixb
local Mxb=kb.score(Lxb)
if Mxb>0 and(not Exb or Kxb<Fxb or(Kxb==Fxb and Mxb>Gxb))then
Exb,Fxb,Gxb={uuid=Hxb,id=Jxb,u=Lxb},Kxb,Mxb
end
end
end
end
if not Exb then
return
end
local Nxb,Oxb
for Pxb,Qxb in ipairs(Axb)do
if not V.isFarm(Qxb.id)and not V.allyBuff(Qxb.id)and Qxb.uuid~=O.evolveUnit then
local Rxb=kb.score(Qxb.u)
if not Nxb or Rxb<Oxb then
Nxb,Oxb=Qxb,Rxb
end
end
end
if not Nxb then
return
end
yxb.tried[Exb.id]=os.time()
local Sxb=0
for Txb in pairs(yxb.tried)do
Sxb=Sxb+1
if Sxb>300 then
yxb.tried[Txb]=nil
end
end
local Uxb,Vxb=gb.levelFor(xxb)
if not Uxb then
return
end
local Wxb=gb.info(Uxb,xxb.key,Vxb,xxb.mod or W.ldMod(Uxb)or W.levelMod(xxb.level))
local Xxb={}
for Yxb,Zxb in ipairs(Axb)do
table.insert(Xxb,Zxb.uuid==Nxb.uuid and Exb.u or Zxb.u)
end
local _xb,ayb=pcall(gb.run,Wxb,gb.teamFrom(Xxb,Wxb.map),{hpMul=1.1})
local byb=_xb and type(ayb)==jse[2091]and(ayb.won or(Wxb.infinite and(tonumber(ayb.wave)or 0)>=0.8*W.infReach(xxb.key)))
if not byb then
F.log(2,jse[3623],string.format(jse[3624],V.name(Exb.id),xxb.label))
return
end
local cyb={}
for dyb,eyb in ipairs(Axb)do
table.insert(cyb,eyb.uuid==Nxb.uuid and Exb.uuid or eyb.uuid)
end
if ab.equipTeam(cyb,jse[3625]..V.name(Exb.id))then
yxb.now={id=Exb.id,out=Nxb.id,key=xxb.key,at=os.time(),ev=Fxb}
F.log(1,jse[3623],string.format(jse[3626],V.name(Exb.id),V.name(Nxb.id),xxb.label,Fxb))
F.saveNow()
end
end
