function eb.upgradeGain(XBb,YBb,ZBb,_Bb,aCb,bCb)
local cCb,dCb=YBb[ZBb],YBb[ZBb+1]
local eCb=(cCb.cd>0 and cCb.damage/cCb.cd or 0)
local fCb=(dCb.cd>0 and dCb.damage/dCb.cd or 0)*V.aoe(dCb.atk,dCb.range)/math.max(0.3,V.aoe(cCb.atk,cCb.range))
local gCb=eCb>0 and XBb*(fCb/eCb-1)or(bCb or 0)
local hCb=YBb[ZBb+2]
if hCb and ZBb+1<YBb.max and hCb.cd>0 and dCb.cd>0 and eCb>0 then
local iCb=XBb*((hCb.damage/hCb.cd)/eCb-1)
local jCb=_Bb+hCb.cost*aCb
if iCb/jCb>gCb/_Bb then
gCb=gCb+(iCb/jCb*_Bb-gCb)*0.5
end
end
local kCb=(dCb.range or 0)>(cCb.range or 0)and(1+((dCb.range-cCb.range)/math.max(1,cCb.range)))or 1
return math.max(0,gCb)*kCb
end
function eb.dpsFor(lCb,mCb)
if mCb<=0 then
return 0
end
local nCb={}
for oCb,pCb in ipairs(lCb)do
if not pCb.farm and not pCb.grif and pCb.gain>0 then
table.insert(nCb,pCb)
end
end
table.sort(nCb,function(qCb,rCb)
return qCb.gain/qCb.cost>rCb.gain/rCb.cost
end)
local sCb,tCb=0,0
for uCb,vCb in ipairs(nCb)do
if mCb<=0 then
break
end
tCb=vCb.gain/vCb.cost
local wCb=math.min(1,mCb/vCb.cost)
sCb=sCb+vCb.gain*wCb
mCb=mCb-vCb.cost*wCb
end
return sCb+math.max(0,mCb)*tCb*0.7
end
function eb.shieldDps(xCb,yCb,zCb,ACb,BCb,CCb,DCb)
