local eTb=table.clone(YSb)
eTb.dmgMul,eTb._dk=dTb,nil
local fTb,gTb=pcall(gb.runRaw,eTb,ZSb,_Sb)
if not(fTb and type(gTb)==jse[2091])then
return nil
