local bic=P.dg.sim[Yhc]
if bic and bic.sig==aic then
return not bic.none and bic or nil
end
local cic={}
for dic,eic in ipairs(V.equipped())do
table.insert(cic,eic.u)
end
if#cic==0 then
return nil
end
local fic=gb.applyFx(gb.info(gb.slim(Vhc.r._l),jse[2811],nil,jb.mod(Vhc.r._l)),_hc)
jb.applyK(fic,Vhc.r._r)
if Xhc then
fic.zone=false
end
local gic=gb.wave(fic,1,true)
if#gic==0 then
bic={none=true,sig=aic,at=os.time()}
else
local hic=gb.evaluate(fic,gb.teamFrom(cic,fic.map))
bic={p=hic.p,wave=hic.wave,won=hic.won,total=fic.total,margin=hic.margin,sig=aic,at=os.time(),zone=fic.zone~=false or nil}
end
P.dg.sim[Yhc]=bic
if U.count(P.dg.sim)>60 then
local iic,jic
for kic,lic in pairs(P.dg.sim)do
if not jic or(lic.at or 0)<jic then
iic,jic=kic,lic.at or 0
end
end
P.dg.sim[iic]=nil
end
F.saveSoon()
return not bic.none and bic or nil
end
function jb.winP(mic)
local nic=tostring(math.min(4,math.max(1,math.ceil(mic.d/5))))
local oic=P.dg.depth[nic]or{runs=0,wins=0}
local pic=U.clamp(0.95-0.015*mic.d,0.5,0.95)
local qic=((tonumber(oic.wins)or 0)+pic*2)/((tonumber(oic.runs)or 0)+2)
local ric,sic=pcall(jb.sim,mic)
if ric and sic and sic.p then
local tic,uic=pcall(gb.styleP,sic,sic.zone==false and jse[3854]or(sic.zone and jse[3790]or nil))
qic=(qic*2+(tic and uic or sic.p))/3
end
return qic,ric and sic or nil
end
function jb.hopeless(vic)
return vic~=nil and vic.won==false and(tonumber(vic.p)or 1)<=0.05
end
function jb.stake(wic)
local xic,yic,zic=jb.res(wic)
return yic+2*zic
end
function jb.curseBar(Aic,Bic)
local Cic=jb.stake(Aic)
if Bic>=15 or Cic>=8 then
return 0.9,jse[4012],Cic
end
if Bic>=10 or Cic>=4 then
return 0.6,jse[4013],Cic
end
return 0.1,jse[4014],Cic
end
function jb.blindCurse(Dic,Eic)
return jb.fxText(jb.fx(Dic,Eic))==jb.fxText(jb.fx(Dic))
end
function jb.curseOk(Fic,Gic,Hic,Iic,Jic)
local Kic=tostring((jb.item(Fic)or{}).name or Fic)
local Lic,Mic,Nic=jb.curseBar(Gic,Hic)
if Lic>0.2 and jb.blindCurse(Gic,Fic)then
return false,string.format(jse[4015],Kic,Nic)
end
local function Oic(Pic)
return Pic==nil or(tonumber(Pic.p)or 1)>=Lic
end
if Iic then
local Qic,Ric=pcall(jb.sim,Iic,nil,true)
if Qic and not Oic(Ric)then
return false,string.format(jse[4016],Kic,(Mic:gsub(jse[4017],jse[4018])),tostring(Ric.margin or jse[2327]))
end
end
if#Jic==0 then
return true
end
local Sic
for Tic,Uic in ipairs(Jic)do
local Vic,Wic=pcall(jb.sim,Uic,Fic,true)
if not Vic or Oic(Wic)then
return true
end
if not Sic or(tonumber(Wic.p)or 0)>(tonumber(Sic.p)or 0)then
Sic=Wic
end
end
return false,string.format(jse[4019],Kic,Mic,tostring(Sic and Sic.margin or jse[2327]))
end
function jb.curseGate(Xic,Yic)
local Zic=jb.roomCurse(Xic.r)
if not Zic then
return true
end
return jb.curseOk(Zic,Yic,Xic.d,Xic,jb.after(Yic,Xic.choice))
end
function jb.payValue()
local _ic,ajc=0,0
for bjc,cjc in ipairs(P.dg.pay or{})do
if type(cjc.items)==jse[2091]then
local djc=tonumber(cjc.gems)or 0
for ejc,fjc in pairs(cjc.items)do
if(tonumber(fjc)or 0)>0 then
djc=djc+W.itemValue(ejc,fjc)
end
end
_ic,ajc=_ic+djc,ajc+1
end
end
if ajc<5 then
return nil
end
return _ic/ajc*0.7
end
jb.LOSS_PRIOR={won=3,n=12}
function jb.lossWin()
local gjc=type(P.dg)==jse[2091]and type(P.dg.lossCalls)==jse[2091]and P.dg.lossCalls or{}
return U.clamp(((tonumber(gjc.won)or 0)+jb.LOSS_PRIOR.won)/((tonumber(gjc.n)or 0)+jb.LOSS_PRIOR.n),0.05,0.95)
end
function jb.pick(hjc)
local ijc,jjc=jb.curses(hjc),jb.lives(hjc)
local kjc=jb.res(hjc)
local ljc=jb.rooms(hjc)
local mjc={}
for njc,ojc in ipairs(ljc)do
table.insert(mjc,tostring(ojc.r._r))
end
local pjc=table.concat(mjc,jse[2955])..string.format(jse[4020],jjc,kjc,ijc,W.teamSig())
if jb._pick and jb._pick.sig==pjc then
return jb._pick.x
end
local qjc,rjc,sjc,tjc
for ujc,vjc in ipairs(ljc)do
local wjc=jb.roomValue(vjc,kjc)
local xjc,yjc
for zjc,Ajc in ipairs(jb.after(hjc,vjc.choice))do
local Bjc=jb.roomValue(Ajc,kjc)
if not xjc or Bjc>xjc then
xjc,yjc=Bjc,Ajc
end
end
local Cjc,Djc=jb.winP(vjc)
local Ejc=Djc~=nil and Djc.won==false
local Fjc=jjc>=3 and 1 or(jjc==2 and 2 or 6)
local Gjc=1-(1-Cjc)^math.max(1,jjc)
vjc.oldScore=Gjc*(wjc+0.6*(xjc or 0))-(1-Cjc)*Fjc
if Ejc then
Cjc=math.min(Cjc,jb.lossWin())
Gjc=Cjc
Fjc=Fjc*2
end
vjc.p,vjc.sim,vjc.value,vjc.nextValue,vjc.nextRoom,vjc.simLost=Cjc,Djc,wjc,xjc or 0,yjc,Ejc or nil
vjc.score=Gjc*(wjc+0.6*(xjc or 0))-(1-Cjc)*Fjc
local Hjc,Ijc,Jjc=pcall(jb.curseGate,vjc,hjc)
if Hjc and not Ijc then
vjc.blocked=Jjc
end
if not vjc.blocked then
if not qjc or vjc.score>qjc.score then
qjc=vjc
end
if Ejc then
if not tjc or vjc.score>tjc.score then
tjc=vjc
end
elseif not sjc or vjc.score>sjc.score then
sjc=vjc
end
end
if not rjc or vjc.score>rjc.score then
rjc=vjc
end
end
if qjc and qjc.simLost and sjc then
F.log(1,jse[4021],string.format(jse[4022],jb.roomName(qjc),tostring(qjc.sim and qjc.sim.margin or jse[2327]),math.floor((1-jb.lossWin())*100+0.5),jb.roomName(sjc)))
elseif qjc and tjc and tjc~=qjc and tjc.oldScore>qjc.score then
F.log(1,jse[4021],string.format(jse[4023],jb.roomName(tjc),tostring(tjc.sim and tjc.sim.margin or jse[2327]),jb.roomName(qjc)))
end
qjc=qjc or rjc
jb._pick={sig=pjc,x=qjc,rooms=ljc}
return qjc
end
function jb.roomName(Kjc)
local Ljc=type(Kjc.r._l)==jse[2091]and Kjc.r._l or{}
return string.format(jse[4024],tostring(Ljc._location_name or Ljc.map or jse[2327]),jb.tagText(Kjc.tags))
end
function jb.screens(Mjc)
