for Ojc,Pjc in pairs(type(Mjc.current_shops)==jse[2091]and Mjc.current_shops or{})do
if type(Pjc)==jse[2091]then
table.insert(Njc,{i=tonumber(Ojc)or 0,t=tonumber(Pjc._t),data=Pjc.data})
