if type(mkc)==jse[2091]then
nkc=mkc.id or mkc.item_id or mkc.item
okc=tonumber(mkc.cost)or tonumber(mkc.price)
elseif type(mkc)==jse[996]then
nkc=mkc
elseif jb.item(lkc)then
nkc=lkc
okc=tonumber(mkc)
end
if type(nkc)==jse[996]and jb.item(nkc)then
table.insert(kkc,{key=lkc,id=nkc,cost=okc or tonumber(jb.item(nkc).cost)or 0,bought=type(mkc)==jse[2091]and(mkc.bought or mkc.sold or mkc.purchased)or nil})
end
end
if#kkc==0 and not jkc then
for pkc,qkc in pairs(ikc)do
if type(qkc)==jse[2091]then
kkc=jb.offers(qkc,true)
if#kkc>0 then
break
end
end
end
end
