jb.LUCK_RESERVE=500
jb.MIN_WORTH=0.02
jb.TOP_WORTH=0.08
function jb.shop(Ekc,Fkc)
local Gkc=jb.cleared(Ekc)
local Hkc=jb.res(Ekc)
local Ikc=1+0.1*(jb.items(Ekc)._curse_shop or 0)
local Jkc=jb.shopAhead(Ekc)and math.ceil(jb.LUCK_RESERVE*Ikc)or 0
local Kkc={}
local Lkc,Mkc={},0
for Nkc,Okc in ipairs(jb.offers(Fkc and Fkc.data))do
Okc.cost=math.ceil(Okc.cost*Ikc)
table.insert(Lkc,tostring(jb.item(Okc.id).name or Okc.id))
if not Okc.bought and not jb.isCurse(Okc.id)then
Okc.luck=tonumber(jb.item(Okc.id).luck_increase)~=nil
Okc.v=jb.itemValue(Okc.id,Ekc)
if not Okc.luck and Okc.v/math.max(1,Okc.cost)<jb.MIN_WORTH then
Mkc=Mkc+1
elseif Okc.v>0 and(Okc.luck or Gkc>=10 or Okc.v/math.max(1,Okc.cost)>=jb.TOP_WORTH)then
table.insert(Kkc,Okc)
end
end
end
table.sort(Kkc,function(Pkc,Qkc)
if Pkc.luck~=Qkc.luck then
return Pkc.luck
end
return Pkc.v/math.max(1,Pkc.cost)>Qkc.v/math.max(1,Qkc.cost)
end)
local Rkc,Skc,Tkc={},0,0
for Ukc,Vkc in ipairs(Kkc)do
if Vkc.cost<=Hkc-(Vkc.luck and 0 or Jkc)then
if jb.buy(Vkc)then
Hkc=jb.res(jb.data())
table.insert(Rkc,string.format(jse[4034],tostring(jb.item(Vkc.id).name or Vkc.id),Vkc.cost))
end
elseif Vkc.cost<=Hkc then
Tkc=Tkc+1
else
Skc=Skc+1
end
end
jb.note(string.format(jse[4035],Gkc,#Lkc>0 and table.concat(Lkc,jse[2204])or jse[4036],#Rkc>0 and(jse[4037]..table.concat(Rkc,jse[2204]))or(Gkc<10 and jse[4038]or(Tkc>0 and jse[4039]or jse[4040])),Hkc,Skc>0 and string.format(jse[4041],Skc)or jse[1010],Tkc>0 and string.format(jse[4042],Tkc,Jkc)or jse[1010],Mkc>0 and string.format(jse[4043],Mkc)or jse[1010]))
F.request(jse[4044],jse[4045])
end
function jb.shrine(Wkc,Xkc)
local Ykc=jb.offers(Xkc and Xkc.data)
local Zkc,_kc=0,{}
local alc
for blc,clc in ipairs(Ykc)do
local dlc=jb.item(clc.id)
table.insert(_kc,tostring(dlc and dlc.name or clc.id))
if jb.isCurse(clc.id)then
local elc,flc,glc=pcall(jb.curseOk,clc.id,Wkc,jb.cleared(Wkc)+1,nil,jb.rooms(Wkc))
if elc and not flc then
alc=glc
end
else
Zkc=Zkc+jb.itemValue(clc.id,Wkc)
end
end
local hlc= #Ykc>0 and Zkc>0 and not alc
if hlc then
F.request(jse[4046],jse[4047])
else
