end
jb.note(string.format(jse[4048],#_kc>0 and table.concat(_kc,jse[2204])or jse[4036],hlc and jse[4049]or(alc and(jse[4050]..alc)or jse[4051])))
end
function jb.wallet()
local ilc=N.session()and N.session().profile_data or{}
local jlc=ilc.inventory or{}
local klc={gems=tonumber(N.cur(jse[2156]))or 0,gold=tonumber(N.cur(jse[2158]))or 0,items={},units={},unique=0}
for llc,mlc in pairs(jlc.normal_items or{})do
klc.items[llc]=tonumber(mlc)or 0
end
for nlc,olc in pairs(ilc.collection and ilc.collection.owned_units or{})do
klc.units[nlc]=olc.unit_id
end
for plc in pairs(jlc.unique_items or{})do
klc.unique=klc.unique+1
end
