function jb.walletDiff(qlc,rlc)
local slc={}
if rlc.gems~=qlc.gems then
table.insert(slc,string.format(jse[4052],rlc.gems-qlc.gems))
end
if rlc.gold~=qlc.gold then
table.insert(slc,string.format(jse[4053],rlc.gold-qlc.gold))
end
for tlc,ulc in pairs(rlc.items)do
if ulc~=(qlc.items[tlc]or 0)then
table.insert(slc,string.format(jse[4054],ulc-(qlc.items[tlc]or 0),tostring(tlc)))
end
end
for vlc,wlc in pairs(rlc.units)do
if not qlc.units[vlc]then
table.insert(slc,jse[4055]..V.name(wlc))
end
end
if rlc.unique~=qlc.unique then
table.insert(slc,string.format(jse[4056],rlc.unique-qlc.unique))
end
return#slc>0 and table.concat(slc,jse[2204])or jse[4057]
end
function jb.openChests(xlc,ylc)
local zlc,Alc,Blc=jb.res(xlc)
local Clc=jb.lives(xlc)
local Dlc=jb.cleared(xlc)
if not(ylc or Dlc>=jb.ROOMS or Clc<=1)then
jb.note(string.format(jse[4058],Dlc,Alc,Blc,jb.luck(xlc)))
F.request(jse[4044],jse[4045])
return
end
local Elc,Flc,Glc=0,0,0
local Hlc=tonumber(N.cur(jse[2156]))or 0
local Ilc=jb.wallet()
for Jlc=1,Alc+Blc+4 do
local Klc,Llc,Mlc=jb.res(jb.data())
if Llc+Mlc<=0 or Glc>=2 then
break
end
local Nlc,Olc
if Llc>0 then
Nlc,Olc=F.request(jse[4059],jse[4060])
else
Nlc,Olc=F.request(jse[4059],jse[4060],true)
end
if Nlc and Olc~=nil then
F.log(1,jse[4021],jse[4061]..(type(Olc)==jse[2091]and U.json(U.plain(Olc)):sub(1,300)or tostring(Olc)))
end
local Plc=U.now()
while U.now()-Plc<4 do
local Qlc,Rlc,Slc=jb.res(jb.data())
if Rlc<Llc or Slc<Mlc then
break
end
task.wait(0.25)
end
local Tlc,Ulc,Vlc=jb.res(jb.data())
if Ulc<Llc then
Elc=Elc+(Llc-Ulc)
Glc=0
elseif Vlc<Mlc then
Flc=Flc+(Mlc-Vlc)
Glc=0
else
Glc=Glc+1
end
task.wait(1)
if Ulc<Llc or Vlc<Mlc then
local Wlc=jb.wallet()
local Xlc=jb.walletDiff(Ilc,Wlc)
F.log(1,jse[4021],(Vlc<Mlc and jse[4062]or jse[4061])..Xlc)
P.dg.pay=P.dg.pay or{}
local Ylc={}
for Zlc,_lc in pairs(Wlc.items)do
if _lc~=(Ilc.items[Zlc]or 0)then
Ylc[Zlc]=_lc-(Ilc.items[Zlc]or 0)
end
end
table.insert(P.dg.pay,{at=os.time(),rare=Vlc<Mlc,gems=Wlc.gems-Ilc.gems,luck=jb.luck(xlc),paid=Xlc,items=Ylc})
while#P.dg.pay>60 do
table.remove(P.dg.pay,1)
end
Ilc=Wlc
end
end
jb.note(string.format(jse[4063],Elc,Flc,ylc and jse[4064]or(Clc<=1 and jse[4065]or jse[4066]),jb.luck(xlc),(tonumber(N.cur(jse[2156]))or 0)-Hlc))
local amc,bmc,cmc=jb.res(jb.data())
if(ylc or Dlc>=jb.ROOMS)and bmc+cmc>0 then
jb.note(string.format(jse[4067],bmc,cmc))
W.rec(jse[2811]).restUntil=os.time()+1800
return jse[4068]
end
if not ylc then
F.request(jse[4044],jse[4045])
end
end
function jb.act(dmc)
local emc,fmc=jb.state(dmc)
jb.logState(dmc,emc)
if emc==jse[4028]then
return false
end
if emc==jse[4027]then
jb.note(string.format(jse[4069],tostring(fmc and fmc.t)))
F.request(jse[4044],jse[4045])
return true
end
if emc==jse[2856]then
F.request(jse[4070],jse[4071])
jb.note(jse[4072])
P.dg.lives,P.dg.lost,P.dg.bailed,P.dg.bails=5,{},{},{}
elseif emc==jse[4025]then
if jb.openChests(dmc,true)==jse[4068]then
return jse[4068]
end
F.request(jse[4044],jse[4045])
local gmc,hmc,imc=jb.res(jb.data())
table.insert(P.dg.runs,1,{at=os.time(),depth=jb.ROOMS,items=U.count(jb.items(dmc)),left=hmc+imc})
while#P.dg.runs>10 do
table.remove(P.dg.runs)
end
jb.note(jse[4073])
elseif emc==jse[3158]then
jb.shop(dmc,fmc)
elseif emc==jse[3977]then
jb.shrine(dmc,fmc)
elseif emc==jse[4026]then
if jb.openChests(dmc,false)==jse[4068]then
return jse[4068]
end
end
return true
end
function jb.launch(jmc)
local kmc=jb.data()
if not kmc then
F.backoff(jse[3498],30)
return false
end
if not kmc._started then
if not(O.dungeonStart or O.onlyDungeons)then
return false
end
local lmc,mmc=F.request(jse[4074],jse[4075])
task.wait(2.5)
kmc=jb.data()
if not(lmc and kmc and kmc._started)then
F.log(1,jse[4021],jse[4076]..tostring(mmc)..jse[4077])
W.rec(jse[2811]).restUntil=os.time()+1800
F.backoff(jse[3498],10)
return false
end
P.dg.lost,P.dg.bailed,P.dg.bails={},{},{}
