function bb.buildPath()
bb.samples={}
local hqc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not hqc then
return
end
for iqc,jqc in pairs(hqc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[iqc.Name])then
local kqc={}
for lqc,mqc in ipairs(jqc.points or{})do
table.insert(kqc,mqc.part.Position)
end
local nqc=0
for oqc=2,#kqc do
nqc=nqc+(kqc[oqc]-kqc[oqc-1]).Magnitude
end
local pqc=0
for qqc=2,#kqc do
local rqc,sqc=kqc[qqc-1],kqc[qqc]
local tqc=(sqc-rqc).Magnitude
local uqc=math.max(1,math.floor(tqc/2))
for vqc=0,uqc-1 do
local wqc=rqc:Lerp(sqc,vqc/uqc)
table.insert(bb.samples,{pos=wqc,prog=(pqc+tqc*vqc/uqc)/math.max(1,nqc),lane=iqc.Name})
end
pqc=pqc+tqc
end
if kqc[#kqc]then
table.insert(bb.samples,{pos=kqc[#kqc],prog=1,lane=iqc.Name})
end
end
end
pcall(bb.readHidden,hqc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local xqc=tonumber(bb.ld and bb.ld._portal_lanes)
local yqc=gb.laneList(bb.samples)
if xqc and xqc>=1 and yqc and#yqc>xqc then
bb.laneWant=xqc
end
bb.laneTotal=yqc and#yqc or 1
bb.countLanes()
end
function bb.readHidden(zqc)
local Aqc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(Aqc)~=jse[2091]or not next(Aqc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local Bqc
for Cqc,Dqc in pairs(zqc)do
if Aqc[Cqc.Name]and type(Dqc.points)==jse[2091]and#Dqc.points>=2 then
local Eqc={}
for Fqc,Gqc in ipairs(Dqc.points)do
Eqc[Fqc]=U.flat(Gqc.part.Position)
end
local Hqc={}
for Iqc,Jqc in ipairs(bb.samples)do
local Kqc=tostring(Jqc.lane)
Hqc[Kqc]=Hqc[Kqc]or{}
table.insert(Hqc[Kqc],Jqc)
end
local Lqc,Mqc
for Nqc,Oqc in pairs(Hqc)do
local Pqc=0
for Qqc=1,#Eqc,math.max(1,math.floor(#Eqc/20))do
local Rqc=math.huge
for Sqc,Tqc in ipairs(Oqc)do
local Uqc=(U.flat(Tqc.pos)-Eqc[Qqc]).Magnitude
if Uqc<Rqc then
Rqc=Uqc
end
end
Pqc=Pqc+Rqc
end
if not Mqc or Pqc<Mqc then
Lqc,Mqc=Nqc,Pqc
end
end
local Vqc,Wqc,Xqc,Yqc,Zqc,_qc={},nil,nil,nil,0,0
for arc,brc in ipairs(Eqc)do
local crc,drc=nil,math.huge
for erc,frc in ipairs(Hqc[Lqc])do
local grc=(U.flat(frc.pos)-brc).Magnitude
if grc<drc then
drc,crc=grc,frc.prog
end
end
_qc=math.max(_qc,drc)
if Xqc then
local hrc=crc-Xqc
local irc=(hrc>0.002 and 1)or(hrc< -0.002 and-1)or Yqc
if Yqc and irc and irc~=Yqc then
table.insert(Vqc,math.floor(Xqc*1000+0.5)/1000)
end
Yqc,Zqc=irc or Yqc,Zqc+math.abs(hrc)
else
Wqc=crc
end
Xqc=crc
if arc%50==0 then
task.wait()
end
end
if Xqc and _qc<=8 then
table.insert(Vqc,math.floor(Xqc*1000+0.5)/1000)
Bqc=Bqc or{}
Bqc[Cqc.Name]={from=math.floor((Wqc or 0)*1000+0.5)/1000,len=math.floor(Zqc*1000+0.5)/1000,turns=Vqc,road=Lqc}
end
end
end
if not Bqc then
return
end
local jrc=bb.ld.map
P.maps[jrc]=P.maps[jrc]or{}
local krc=P.maps[jrc].hidden
P.maps[jrc].hidden=Bqc
if type(krc)~=jse[2091]then
for lrc,mrc in pairs(Bqc)do
F.log(1,jse[2760],string.format(jse[4156],lrc,mrc.len,tostring(mrc.road),math.floor((#mrc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local nrc,orc,prc={},0,0
for qrc,rrc in ipairs(bb.samples)do
local trc=tostring(rrc.lane)
if not nrc[trc]then
orc=orc+1
end
nrc[trc]=(nrc[trc]or 0)+1
prc=prc+1
end
bb.laneCount={n=orc,by=nrc,avg=orc>0 and prc/orc or 1}
if orc>=2 then
local urc,vrc=pcall(gb.laneSep,bb.samples)
local wrc=P.maps[bb.mapKey()]
if urc and vrc and type(wrc)==jse[2091]then
wrc.sep=vrc
end
end
