end
local xrc,yrc={},0
for zrc,Arc in ipairs(workspace._UNITS:GetChildren())do
local Brc=Arc:FindFirstChild(jse[2155])
if Brc and Brc:FindFirstChild(jse[4157])and Brc.player.Value==nil and Brc:FindFirstChild(jse[4158])and Arc:FindFirstChild(jse[3349])then
local Crc=tostring(Brc.lane.Value)
if not xrc[Crc]then
xrc[Crc]=true
yrc=yrc+1
end
end
end
if yrc==0 then
if U.now()-(bb.startT or U.now())>45 then
bb.laneWant=nil
F.log(1,jse[2760],jse[4159])
return true
end
return false
end
bb.laneFirst=bb.laneFirst or U.now()
if yrc<bb.laneWant and U.now()-bb.laneFirst<bb.LANE_WAIT then
return false
end
local Drc,Erc={},{}
for Frc,Grc in ipairs(bb.samples)do
if xrc[tostring(Grc.lane)]then
table.insert(Drc,Grc)
end
end
if#Drc==0 then
bb.laneWant=nil
return true
end
for Hrc in pairs(xrc)do
table.insert(Erc,Hrc)
