table.sort(Erc)
bb.samples,bb.laneCut=Drc,table.concat(Erc,jse[2406])
bb.countLanes()
local Irc,Jrc=pcall(bb.buildCandidates)
if not Irc then
F.log(1,jse[2478],jse[4160]..tostring(Jrc))
end
F.log(1,jse[2760],string.format(jse[4161],bb.laneWant,bb.laneCut))
if bb.info and O.simSpots and not bb.joinedMid and not bb.random and not bb.infinite and not bb.trialId then
bb.planning=U.now()
task.spawn(function()
local Krc,Lrc=pcall(bb.planSpots)
bb.planning=nil
