function bb.infStop(Zrc)
local _rc=0
for asc,bsc in ipairs(U.list(N.GS.DAILY_INFINITE_REWARDS))do
_rc=math.max(_rc,tonumber(bsc.wave)or 0)
end
if _rc<=0 or Zrc<=_rc+1 then
return
end
local csc=P.train.on
if bb.trainee and csc and csc.have+(csc.got or 0)+(bb.trainTk or 0)<csc.need then
return
end
if not ab.every(jse[4168],60)then
return
end
local dsc=W.rec(bb.key)
local esc=tonumber(dsc.timed)or 0
local fsc=W.INF_PAY
local gsc
if Zrc>=(fsc.cap+fsc.less)/fsc.per then
gsc=0
else
local hsc=bb.infWaveAt or{}
local isc,jsc=hsc[Zrc],hsc[Zrc-5]
if isc and jsc and isc>jsc then
gsc=fsc.per*5/((isc-jsc)/60)
end
if not gsc then
gsc=(esc>0 and(dsc.sec or 0)>0)and math.max(0.5,(dsc.gems or 0)/(dsc.sec/60))or 2.5
end
end
local ksc=pcall(W.pick)
local lsc
for msc,nsc in ipairs(ksc and W.lastScored or{})do
if nsc.kind~=jse[2111]and(not lsc or(nsc.score or 0)>(lsc.score or 0))then
lsc=nsc
end
end
if not lsc or(lsc.score or 0)<=gsc then
return
end
bb.stopping=true
F.log(1,jse[2760],string.format(jse[4169],Zrc,gsc,lsc.score,lsc.label))
bb.sellAll()
end
function bb.trainLeave(osc)
