local rsc,ssc,tsc=pcall(W.infDaily,N.prof(),bb.ld.id,(W.infReach(bb.key)))
if rsc and(ssc or 0)>0 and tsc>0 and osc<=tsc then
F.status(jse[3313],string.format(jse[4170],V.name(psc.id),psc.what,tsc))
return
end
bb.stopping=true
F.log(1,jse[2760],string.format(jse[4171],V.name(psc.id),psc.what,U.fmt(qsc),U.fmt(psc.need),osc))
