function bb.studyRun(FLc)
local GLc=U.now()
while F.alive and not(bb.finished or bb.result)and(bb.planning or U.now()-GLc<20)do
task.wait(1)
end
local function HLc()
return F.alive and not(bb.finished or bb.result)and O.mapStudy~=false and not O.lowLag and F.where==jse[2164]
end
if not HLc()then
return
end
local ILc,JLc,KLc=FLc.info,FLc.team,FLc.base
local LLc=ILc.timeLimit~=nil
local MLc=LLc and 1 or math.max(1,tonumber(FLc.hard)or 1)
local NLc={MLc*0.95,MLc*1.05}
local OLc=bb.bookFor(ILc)
local PLc={key=FLc.key,label=bb.label(),n=OLc and tonumber(OLc.n)or 0,run=0,timed=LLc,kills=ILc.killScore and true or nil,hp=MLc,at=os.time()}
bb.study=PLc
local QLc,RLc,SLc,TLc,ULc={},0,0,0,0
for VLc,WLc in ipairs(FLc.attackers)do
local XLc,YLc,ZLc,_Lc=bb.studyMoves(WLc,FLc.scale)
QLc[WLc.id]=XLc
RLc,SLc,TLc,ULc=RLc+ #(WLc.spots or{}),SLc+YLc,TLc+ #XLc,ULc+_Lc
if not HLc()then
return
end
end
PLc.moves=TLc
F.log(1,jse[2845],string.format(jse[4340],PLc.label,RLc,SLc,TLc,ULc>0 and string.format(jse[4341],ULc)or jse[1010]))
local aMc={}
local function bMc(cMc)
return{samples=bb.samples,cache=aMc,spots=cMc,style=KLc.style,list=KLc.list,hybridHill=KLc.hybridHill}
end
local function dMc(eMc)
local fMc=0
for gMc,hMc in pairs(eMc)do
local iMc=bb.spotRec(gMc,hMc)
if iMc then
fMc=fMc+(tonumber(iMc.wins)or 0)*200-((tonumber(iMc.runs)or 0)-(tonumber(iMc.wins)or 0))*1500
end
end
return fMc
end
local function jMc(kMc)
local lMc,mMc,nMc=0,0,0
for oMc,pMc in ipairs(NLc)do
local qMc=os.clock()
local rMc=gb.runRaw(ILc,JLc,{hpMul=pMc,layout=bMc(kMc),bg=true})
lMc,mMc,nMc=lMc+gb.objective(rMc),mMc+(tonumber(rMc.kills)or 0),nMc+(tonumber(rMc.wave)or 0)
task.wait(math.clamp((os.clock()-qMc)*3,0.25,FLc.pauseMax or 1.5))
if not HLc()then
return nil
end
end
PLc.n,PLc.run=PLc.n+1,PLc.run+1
return lMc/ #NLc*100+dMc(kMc),mMc/ #NLc,nMc/ #NLc
end
local function sMc(tMc)
local uMc={}
for vMc,wMc in pairs(tMc)do
uMc[vMc]=wMc
end
return uMc
end
local function xMc(yMc,zMc,AMc)
for BMc,CMc in pairs(yMc)do
if BMc~=zMc and(U.flat(CMc)-U.flat(AMc)).Magnitude<4.5 then
return true
end
end
return false
end
local DMc={spots=sMc(KLc.spots)}
DMc.s,DMc.kills,DMc.wave=jMc(DMc.spots)
if not DMc.s then
return bb.studyEnd(PLc,FLc,nil)
end
PLc.baseKills,PLc.baseWave=DMc.kills,DMc.wave
PLc.bestKills,PLc.bestWave=DMc.kills,DMc.wave
if OLc and OLc.aside==nil then
local EMc,FMc=sMc(DMc.spots),0
for GMc,HMc in ipairs(FLc.attackers)do
local IMc=OLc.spots[HMc.id]
local JMc=type(IMc)==jse[2091]and tonumber(IMc[1])and tonumber(IMc[3])and bb.nearSpot(HMc.spots,tonumber(IMc[1]),tonumber(IMc[3]))or nil
if JMc and JMc~=EMc[HMc.id]and not xMc(EMc,HMc.id,JMc)then
EMc[HMc.id]=JMc
FMc=FMc+1
end
end
if FMc>0 then
local KMc,LMc,MMc=jMc(EMc)
if not KMc then
return bb.studyEnd(PLc,FLc,DMc)
end
if KMc>DMc.s then
DMc={spots=EMc,s=KMc,kills=LMc,wave=MMc}
PLc.bestKills,PLc.bestWave=LMc,MMc
end
end
end
local NMc,OMc=U.now(),PLc.run
local function PMc(QMc)
if not(QMc.s and QMc.s>DMc.s+math.max(50,math.abs(DMc.s)*0.005))then
return false
end
DMc=QMc
PLc.bestKills,PLc.bestWave,PLc.better=QMc.kills,QMc.wave,(PLc.better or 0)+1
pcall(bb.bookSave,ILc,FLc,DMc,PLc)
return true
end
local function RMc()
if PLc.run-OMc>=60 or U.now()-NMc>240 then
NMc,OMc=U.now(),PLc.run
F.log(1,jse[2845],bb.studyWords(PLc))
end
end
local SMc={DMc}
for TMc,UMc in ipairs(FLc.attackers)do
local VMc={}
for WMc,XMc in ipairs(SMc)do
table.insert(VMc,XMc)
for YMc,ZMc in ipairs(QLc[UMc.id]or{})do
if ZMc~=XMc.spots[UMc.id]and not xMc(XMc.spots,UMc.id,ZMc)then
local _Mc=sMc(XMc.spots)
_Mc[UMc.id]=ZMc
local aNc,bNc,cNc=jMc(_Mc)
if not aNc then
return bb.studyEnd(PLc,FLc,DMc)
end
local dNc={spots=_Mc,s=aNc,kills=bNc,wave=cNc}
table.insert(VMc,dNc)
PMc(dNc)
RMc()
end
end
end
table.sort(VMc,function(eNc,fNc)
return(eNc.s or-1e18)>(fNc.s or-1e18)
end)
SMc={}
for gNc=1,math.min(bb.STUDY_BEAM,#VMc)do
table.insert(SMc,VMc[gNc])
end
end
local hNc={}
for iNc,jNc in ipairs(FLc.attackers)do
if QLc[jNc.id]and#QLc[jNc.id]>0 then
table.insert(hNc,jNc.id)
end
end
while HLc()and#hNc>0 do
local kNc=sMc(DMc.spots)
for lNc=1,math.min(2,#hNc)do
local mNc=hNc[math.random(#hNc)]
local nNc=QLc[mNc]
local oNc=nNc[math.random(#nNc)]
if not xMc(kNc,mNc,oNc)then
kNc[mNc]=oNc
end
end
local pNc,qNc,rNc=jMc(kNc)
if not pNc then
break
end
PMc({spots=kNc,s=pNc,kills=qNc,wave=rNc})
RMc()
end
bb.studyEnd(PLc,FLc,DMc)
end
bb.STUDY_INF_WAIT=240
function bb.validOpen(sNc,tNc)
local uNc=N.PC.raycast(sNc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not uNc then
return nil
end
if not N.PC.is_valid_raycast_hit(uNc.Instance,tNc)then
return nil
end
local vNc=uNc.Position
if bb.blockedSpot(vNc)then
return nil
end
local wNc=(tonumber(tNc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(wNc*2,2.5,wNc*2)
bb.probe.CFrame=CFrame.new(vNc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return vNc
end
function bb.studyInfinite()
if O.mapStudy==false or O.lowLag or not(bb.info and bb.infinite)or bb.kind==jse[2547]then
return
end
local xNc=bb.info
local function yNc()
return not F.alive or bb.finished or bb.result or F.where~=jse[2164]or O.mapStudy==false or bb.withOthers or bb.fastAlways
end
local zNc,ANc={},{}
for BNc,CNc in ipairs(bb.team or{})do
table.insert(zNc,CNc.u)
if not V.isFarm(CNc.id)and not V.allyBuff(CNc.id)and CNc.uuid~=bb.trainee and V.rows(CNc.id)then
local DNc,ENc=pcall(V.score,CNc.u,bb.mod)
table.insert(ANc,{e=CNc,id=CNc.id,sc=DNc and ENc or 0})
end
end
if#ANc==0 then
return
end
table.sort(ANc,function(FNc,GNc)
return FNc.sc>GNc.sc
end)
local function HNc()
local INc,JNc={},0
for KNc,LNc in ipairs(ANc)do
for MNc,NNc in ipairs(bb.mine or{})do
local ONc=NNc:FindFirstChild(jse[2155])
local PNc=ONc and ONc:FindFirstChild(jse[2468])
if PNc and PNc.Value==LNc.e.uuid and ONc:FindFirstChild(jse[2469])and ONc.id.Value==LNc.id then
INc[LNc.id]=NNc:GetPivot().Position
JNc=JNc+1
break
end
end
end
return INc,JNc
end
local QNc=U.now()
local RNc,SNc=HNc()
while SNc< #ANc and U.now()-QNc<bb.STUDY_INF_WAIT do
task.wait(5)
if yNc()then
return
end
RNc,SNc=HNc()
end
if SNc==0 or yNc()then
return
end
local TNc={}
local function UNc(VNc)
local WNc=VNc.hybrid_placement and not VNc.hill_unit
local XNc=WNc and bb.hybridHill
local YNc=((VNc.hill_unit or XNc)and jse[2871]or(WNc and jse[4268])or jse[4269])..jse[2227]..tostring(VNc.override_hitbox_radius or jse[1010])
if TNc[YNc]then
return TNc[YNc]
end
local ZNc={}
local _Nc=XNc and bb.hillData(VNc)or VNc
for aOc,bOc in ipairs(bb.cands or{})do
local cOc=bb.validOpen(bOc,_Nc)
if cOc then
table.insert(ZNc,cOc)
end
if aOc%40==0 then
task.wait()
end
end
TNc[YNc]=ZNc
return ZNc
end
local dOc={info=xNc,team=gb.teamFrom(zNc,xNc.map),key=bb.bookKey(xNc),hard=1,scale=tonumber(xNc.rangeScale)or 1,attackers={},pauseMax=4,inf=true}
local eOc={spots={},style=jse[3033],hybridHill=bb.hybridHill and true or false}
for fOc,gOc in ipairs(ANc)do
local hOc=(gb.holds(gOc.id)and not V.killFed(gOc.id))and true or false
local iOc=hOc and{}or table.clone(UNc(gOc.e.data))
if yNc()then
return
end
local jOc=RNc[gOc.id]
if jOc then
local kOc=bb.nearSpot(iOc,jOc.X,jOc.Z)
if not kOc then
kOc=jOc
table.insert(iOc,jOc)
end
eOc.spots[gOc.id]=kOc
end
if#iOc>0 then
table.insert(dOc.attackers,{id=gOc.id,e=gOc.e,spots=iOc})
end
end
dOc.base=eOc
bb.studyPool=dOc
F.log(1,jse[2845],string.format(jse[4342],bb.label(),SNc))
bb.studyRun(dOc)
