local function mOc(nOc,oOc)
return lOc.kills and string.format(jse[4280],math.floor((tonumber(nOc)or 0)+0.5))or string.format(jse[4343],tonumber(oOc)or 0,tonumber(lOc.hp)or 1)
end
return string.format(jse[4344],tostring(lOc.label),tonumber(lOc.n)or 0,tonumber(lOc.run)or 0,mOc(lOc.bestKills,lOc.bestWave),mOc(lOc.baseKills,lOc.baseWave),(lOc.better or 0)>0 and jse[4345]or jse[1010])
end
function bb.bookSave(pOc,qOc,rOc,sOc)
P.mapBook=type(P.mapBook)==jse[2091]and P.mapBook or{}
local tOc={}
for uOc,vOc in pairs(rOc.spots or{})do
tOc[uOc]={math.floor(vOc.X*10+0.5)/10,math.floor(vOc.Y*10+0.5)/10,math.floor(vOc.Z*10+0.5)/10}
end
P.mapBook[qOc.key]={spots=tOc,style=qOc.base.style,hp=sOc.hp,n=sOc.n,kills=rOc.kills and math.floor(rOc.kills+0.5)or nil,wave=rOc.wave and math.floor(rOc.wave*10+0.5)/10 or nil,base=sOc.baseWave and math.floor(sOc.baseWave*10+0.5)/10 or nil,label=sOc.label,map=pOc.map,killScore=sOc.kills,at=os.time()}
local wOc={}
for xOc,yOc in pairs(P.mapBook)do
table.insert(wOc,{k=xOc,at=type(yOc)==jse[2091]and tonumber(yOc.at)or 0})
end
if#wOc>bb.BOOK_MAX then
table.sort(wOc,function(zOc,AOc)
return zOc.at>AOc.at
end)
for BOc=bb.BOOK_MAX+1,#wOc do
P.mapBook[wOc[BOc].k]=nil
end
end
F.saveSoon()
