if FOc then
FOc.n=COc.n
F.saveSoon()
elseif COc.run>0 then
pcall(bb.bookSave,DOc.info,DOc,EOc,COc)
end
end
if COc.run>0 then
F.log(1,jse[2845],bb.studyWords(COc))
end
