bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
bb.HIVE_TRY_EVERY,bb.HIVE_TRIALS=3,3
function bb.layoutRecFor(YOc,ZOc)
local _Oc=bb.bookKey(YOc)
P.layoutRec=type(P.layoutRec)==jse[2091]and P.layoutRec or{}
local aPc=P.layoutRec[_Oc]
if type(aPc)~=jse[2091]then
if not ZOc then
return nil
end
aPc={at=os.time()}
P.layoutRec[_Oc]=aPc
if U.count(P.layoutRec)>80 then
local bPc,cPc
for dPc,ePc in pairs(P.layoutRec)do
local fPc=type(ePc)==jse[2091]and tonumber(ePc.at)or 0
if not cPc or fPc<cPc then
bPc,cPc=dPc,fPc
end
end
P.layoutRec[bPc]=nil
end
end
return aPc
end
function bb.layoutAdd(gPc,hPc,iPc,jPc,kPc)
gPc.runs,gPc.wins=(tonumber(gPc.runs)or 0)+1,(tonumber(gPc.wins)or 0)+(hPc and 1 or 0)
gPc.sec,gPc.wave=type(gPc.sec)==jse[2091]and gPc.sec or{},type(gPc.wave)==jse[2091]and gPc.wave or{}
if hPc and tonumber(iPc)then
table.insert(gPc.sec,math.floor(iPc+0.5))
end
table.insert(gPc.wave,tonumber(jPc)or 0)
if tonumber(kPc)then
gPc.kills=type(gPc.kills)==jse[2091]and gPc.kills or{}
table.insert(gPc.kills,math.floor(tonumber(kPc)))
while#gPc.kills>bb.LAYOUT_KEEP do
table.remove(gPc.kills,1)
end
end
while#gPc.sec>bb.LAYOUT_KEEP do
table.remove(gPc.sec,1)
end
while#gPc.wave>bb.LAYOUT_KEEP do
table.remove(gPc.wave,1)
end
end
function bb.layoutJudge(lPc,mPc,nPc,oPc,pPc)
pPc=pPc or jse[4351]
local qPc,rPc=tonumber(lPc and lPc.runs)or 0,tonumber(mPc and mPc.runs)or 0
if qPc<1 or rPc<bb.LAYOUT_CONTROL then
return nil
end
if oPc and type(lPc.kills)==jse[2091]and type(mPc.kills)==jse[2091]and#lPc.kills>=1 and#mPc.kills>=bb.LAYOUT_CONTROL then
local sPc,tPc=bb.labMedian(lPc.kills),bb.labMedian(mPc.kills)
if sPc and tPc and sPc<tPc*0.97 and(#lPc.kills>=2 or sPc<tPc*0.85)then
return string.format(jse[4352],sPc,tPc,pPc)
end
