local uPc,vPc=(tonumber(lPc.wins)or 0)/qPc,(tonumber(mPc.wins)or 0)/rPc
if not nPc and vPc>=0.5 then
if uPc+0.25<vPc and(qPc>=2 or(uPc==0 and vPc>=0.9 and rPc>=3))then
return string.format(jse[4353],tonumber(lPc.wins)or 0,qPc,qPc==1 and jse[1010]or jse[1937],tonumber(mPc.wins)or 0,rPc,pPc)
end
local wPc,xPc=bb.labMedian(lPc.sec),bb.labMedian(mPc.sec)
