MPc.spots[RPc]=SPc
end
MPc.real={runs=LPc.runs,wins=LPc.wins,sec=LPc.sec,wave=LPc.wave,kills=LPc.kills}
MPc.hive,MPc.aside=os.time(),nil
FPc.hiveUnit=nil
F.log(1,jse[4257],string.format(jse[4360],QPc))
