if not XPc(VPc.id)or V.toggleOf(VPc.id)then
return nil
end
local YPc,ZPc,_Pc,aQc=1,0,0,{}
local bQc=bb.hurtSamples()
for cQc,dQc in ipairs(bb.mine or{})do
local eQc=dQc._stats
local fQc=eQc.id.Value
if eQc:FindFirstChild(jse[2344])and not V.isFarm(fQc)and not V.allyBuff(fQc)then
local gQc,hQc=U.flat(dQc:GetPivot().Position),eQc.range.Value
if XPc(fQc)and not V.toggleOf(fQc)then
_Pc=_Pc+1
table.insert(aQc,{p=gQc,r=hQc})
else
for iQc,jQc in ipairs(bQc)do
if(U.flat(jQc.pos)-gQc).Magnitude<=hQc then
YPc,ZPc=math.min(YPc,jQc.prog),math.max(ZPc,jQc.prog)
end
end
end
end
end
if ZPc<=YPc then
YPc,ZPc=0.75,0.98
end
local kQc=(WPc or _Pc)+1
local lQc=({YPc,ZPc,(YPc+ZPc)/2,YPc-(ZPc-YPc)/2})[kQc]
if not lQc then
return nil
end
local mQc=V.range(VPc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local nQc={}
for oQc,pQc in ipairs(bb.cands)do
local qQc,rQc,sQc=U.flat(pQc),0,0
for tQc,uQc in ipairs(bQc)do
if(U.flat(uQc.pos)-qQc).Magnitude<=mQc then
sQc=sQc+1
if math.abs(uQc.prog-lQc)<=0.05 then
rQc=rQc+1
local vQc=U.flat(uQc.pos)
for wQc,xQc in ipairs(aQc)do
if(vQc-xQc.p).Magnitude<=xQc.r then
rQc=rQc-0.5
break
end
end
end
end
end
if rQc>0 then
table.insert(nQc,{pos=pQc,sc=rQc,cov=sQc})
end
if oQc%60==0 then
task.wait()
end
end
table.sort(nQc,function(yQc,zQc)
return yQc.sc>zQc.sc
end)
for AQc,BQc in ipairs(nQc)do
local CQc=bb.valid(BQc.pos,VPc.data)
if CQc then
F.log(1,jse[4196],string.format(jse[4368],V.name(VPc.id),bb.CONTROL_WORDS[kQc],math.floor(lQc*100+0.5)))
return CQc,BQc.cov,lQc
end
if AQc%20==0 then
task.wait()
end
end
return nil
end
