local sUc=bb.money()
local tUc=P.caps[nUc.uuid]and bb.count(nUc.uuid)or nil
local uUc,vUc=F.request(jse[4374],jse[4375],nUc.uuid,N.Util.CFramePLV(qUc,bb.lookAt(qUc)))
if uUc and vUc then
if tUc and tUc>=(tonumber(P.caps[nUc.uuid])or math.huge)then
F.log(1,jse[4196],string.format(jse[4376],V.name(nUc.id),tostring(P.caps[nUc.uuid])))
P.caps[nUc.uuid],P.capsAt[nUc.uuid]=nil,nil
F.saveSoon()
end
bb.spent=bb.spent+(nUc.data.cost or 0)
