function bb.learn()
local Nbd=bb.calRun and bb.calRun.potBy
if type(Nbd)~=jse[2091]then
return
end
pcall(bb.sampleHelpers,true)
local Obd={}
for Pbd,Qbd in pairs(bb.ownDealt or{})do
if not V.isFarm(Qbd.id)then
Obd[Qbd.id]=(Obd[Qbd.id]or 0)+(tonumber(Qbd.v)or 0)
end
end
for Rbd,Sbd in pairs(bb.helperDealt or{})do
if Sbd.owner and V.SUMMONER[Sbd.owner]and not V.droneHelper(Sbd)then
Obd[Sbd.owner]=(Obd[Sbd.owner]or 0)+(tonumber(Sbd.v)or 0)
end
end
local Tbd=type(bb.calRun.potExp)==jse[2091]and bb.calRun.potExp or{}
local Ubd,Vbd=0,0
local Wbd={}
for Xbd,Ybd in pairs(Nbd)do
if Ybd>0 then
Ubd,Vbd=Ubd+(Obd[Xbd]or 0),Vbd+Ybd
local Zbd=tonumber(Tbd[Xbd])or Ybd
if Zbd>0 then
table.insert(Wbd,{id=Xbd,r=(Obd[Xbd]or 0)/Zbd,w=Zbd})
end
end
end
if Ubd<=0 or Vbd<=0 then
return
end
table.sort(Wbd,function(_bd,acd)
return _bd.r<acd.r
end)
local function bcd(ccd)
local dcd,ecd=0,0
for fcd,gcd in ipairs(Wbd)do
if gcd.id~=ccd then
dcd=dcd+gcd.w
end
end
if dcd<=0 then
return nil
end
for hcd,icd in ipairs(Wbd)do
if icd.id~=ccd then
ecd=ecd+icd.w
if ecd>=dcd/2 then
return icd.r
end
end
end
end
bb.lastEff={}
for jcd,kcd in pairs(Nbd)do
local lcd=bcd(jcd)
if kcd>0 and kcd/Vbd>0.02 and lcd and lcd>0 then
local mcd=P.learn[jcd]or{eff=1,n=0,v=6}
V.learnUp(jcd,mcd)
local ncd=math.max(0.02,0.25*math.sqrt(30/(30+mcd.n)))
local ocd=U.clamp(((Obd[jcd]or 0)/kcd)/lcd,0.2,6)
bb.lastEff[jcd]=math.floor(ocd*1000+0.5)/1000
mcd.eff=mcd.eff+(ocd-mcd.eff)*ncd
mcd.n=mcd.n+1
P.learn[jcd]=mcd
end
end
local pcd=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if pcd and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==jse[2091]and P.mapLearn or{}
local qcd=type(P.mapLearn[pcd])==jse[2091]and P.mapLearn[pcd]or{}
for rcd,scd in pairs(bb.lastEff)do
local tcd=type(qcd[rcd])==jse[2091]and qcd[rcd]or{eff=scd,n=0,v=6}
if(tonumber(tcd.v)or 0)<4 then
tcd.eff,tcd.v=(tonumber(tcd.eff)or scd)*V.secRescale(rcd),4
end
if(tonumber(tcd.v)or 0)<5 then
tcd.eff,tcd.v=(tonumber(tcd.eff)or scd)*(V.sumRescale(rcd)or 1),5
end
if(tonumber(tcd.v)or 0)<6 then
tcd.eff,tcd.v=(tonumber(tcd.eff)or scd)*(1-(V.SUMMONER[rcd]and V.SUMMONER[rcd].droneShare or 0)),6
end
local ucd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(tcd.n)or 0))))
tcd.eff=(tonumber(tcd.n)or 0)==0 and scd or((tonumber(tcd.eff)or scd)+(scd-(tonumber(tcd.eff)or scd))*ucd)
tcd.n=(tonumber(tcd.n)or 0)+1
qcd[rcd]=tcd
end
qcd._at=os.time()
P.mapLearn[pcd]=qcd
if U.count(P.mapLearn)>80 then
local vcd,wcd
for xcd,ycd in pairs(P.mapLearn)do
if not wcd or(tonumber(ycd._at)or 0)<wcd then
