function bb.baseVerdict(hid,iid)
local jid=(iid.t or 0)-(hid.t or 0)
if jid<bb.BASE_WIN-1 then
return false
end
local kid=((tonumber(hid.base)or 0)-(tonumber(iid.base)or 0))/jid
if kid<=0 or(tonumber(iid.base)or 0)<=0 then
return false
end
local lid=iid.base/kid
local nid,oid=0,0
local qid,rid=hid.foes or{},iid.foes or{}
for sid,tid in pairs(rid)do
if tid.prog>=bb.BASE_END then
nid=nid+tid.hp
local vid=qid[sid]
if vid then
oid=oid+math.max(0,vid.hp-tid.hp)
end
end
end
for wid,xid in pairs(qid)do
if xid.prog>=bb.BASE_END and not rid[wid]then
oid=oid+xid.hp
end
end
if nid<=0 then
return false
end
local yid=oid/jid
local zid=yid>0 and nid/yid or math.huge
local Aid={baseTime=lid,loss=kid,atEnd=nid,rate=yid,killTime=zid}
return lid<bb.BASE_SOON and zid>lid*bb.BASE_MARGIN,Aid
end
