if not(fnd.fly and not und.air)then
local vnd=und.tg==gnd or(und.full and(rnd-und.at).Magnitude<=und.r)or(und.blast>0 and(rnd-und.tp).Magnitude<=und.blast)
if vnd then
for wnd in pairs(und.fam)do
snd[wnd]=math.max(snd[wnd]or 0,und.need)
end
end
end
end
if not fnd.fly then
for xnd,ynd in ipairs(Pmd)do
if(rnd-ynd.pos).Magnitude<=ynd.r then
snd.slow=math.max(snd.slow or 0,3)
end
end
end
for znd,And in pairs(snd)do
hnd.t[znd]=(hnd.t[znd]or 0)+Nmd
hnd.need[znd]=math.max(hnd.need[znd]or 0,And)
if hnd.t[znd]>=hnd.need[znd]then
hnd.reached[znd]=true
end
end
end
end
end
end
function bb.holdFold()
