if Hnd or(End.reached[Gnd]and Bnd.worked[Gnd])then
local Ind=type(Fnd[Gnd])==jse[2091]and Fnd[Gnd]or{s=0,h=0}
local Jnd,Knd=tonumber(Ind.h)or 0,tonumber(Ind.s)or 0
Ind.s,Ind.h,Ind.at=Knd+1,Jnd+(Hnd and 1 or 0),os.time()
Fnd[Gnd]=Ind
if Hnd and Jnd==0 and End.boss then
Cnd[End.uid..jse[2227]..Gnd]={uid=End.uid,fam=Gnd,took=true}
end
if not Hnd and Ind.h==0 and Knd<gb.HOLD_IMMUNE_N and Ind.s>=gb.HOLD_IMMUNE_N then
Cnd[End.uid..jse[2227]..Gnd]={uid=End.uid,fam=Gnd,n=Ind.s}
end
end
end
if next(Fnd)then
P.holdSeen[End.uid]=Fnd
end
end
end
for Lnd,Mnd in pairs(Cnd)do
local Nnd=(pcall(V.name,Mnd.uid)and V.name(Mnd.uid))or Mnd.uid
if Mnd.took then
F.log(1,jse[2465],string.format(jse[4699],tostring(Nnd),bb.HOLD_WORD[Mnd.fam]or Mnd.fam))
else
F.log(1,jse[2465],string.format(jse[4700],tostring(Nnd),bb.HOLD_WORD[Mnd.fam]or Mnd.fam,Mnd.n))
