bb.drownTarget=nil
return
end
bb.drownTarget=Qnd and Pnd or nil
if Qnd then
return
end
local Tnd=bb.drownState
if not Tnd or Tnd.m~=Pnd.m then
Tnd={m=Pnd.m,moves=0,at=0}
bb.drownState=Tnd
