for Ynd,Znd in ipairs(Rnd)do
if Znd._stats.id.Value==Vnd then
table.insert(Xnd,Znd)
end
end
if#Xnd>=V.cap(Wnd.u)then
local _nd=(tonumber(Wnd.data and Wnd.data.cost)or 0)*Und
local aod,bod
for cod,dod in ipairs(Xnd)do
local eod=dod._stats
local fod,god=U.flat(dod:GetPivot().Position),eod.range.Value
local hod=false
for iod,jod in ipairs(bb.samples)do
if jod.prog>=Pnd.prog and(U.flat(jod.pos)-fod).Magnitude<=god then
hod=true
break
end
end
local kod=eod:FindFirstChild(jse[4198])and tonumber(eod.total_spent.Value)or 0
if not hod and kod<=2.5*_nd and(not bod or kod<bod)then
aod,bod=dod,kod
end
end
if aod and bb.money()+gb.SELL_BACK*bod>=_nd then
Tnd.at,Tnd.moves=U.now(),Tnd.moves+1
local lod,nod=F.request(jse[2274],jse[2472],aod)
if nod==true then
F.log(1,jse[4196],string.format(jse[4701],V.name(Vnd),U.fmt(bod),U.fmt(Pnd.hp)))
task.wait(0.5)
local ood,pod=pcall(bb.place,Wnd,jse[4702])
if not ood then
